Definition wt (c : Z) : Z := if c =? -1 then 1 else c.

Fixpoint wsum (l : list Z) : Z :=
  match l with [] => 0 | c :: t => wt c + wsum t end.

(* [comment removed for export] *)
Definition ncl (nc : list Z) (maxSV : Z) : list Z := firstn (Z.to_nat (maxSV + 1)) nc.

Definition ncount_ok (nc : list Z) (maxSV tableLog : Z) : Prop :=
  0 <= maxSV <= FSE_MAX_SYMBOL_VALUE /\ FSE_MIN_TABLELOG <= tableLog <= FSE_TABLELOG_ABSOLUTE_MAX /\
  maxSV + 1 <= Zlength nc /\
  (forall s, 0 <= s <= maxSV -> -1 <= Znth s nc) /\
  wsum (ncl nc maxSV) = 2^tableLog.

