Definition awrite (l : list (option Z)) (w : Z * Z) : list (option Z) := oupd_nat (Z.to_nat (fst w)) (snd w) l.
Definition apply_writes (ws : list (Z * Z)) (l : list (option Z)) : list (option Z) := fold_left awrite ws l.

