Lemma apply_writes_full ws l : ws_ok ws (length l) -> length ws = length l ->
  forall i, 0 <= i < Zlength l -> exists v, In (i, v) ws /\ nth (Z.to_nat i) (apply_writes ws l) None = Some v.
Proof.
