(* [comment removed for export] *)
Definition oval (o : option Z) : Z := match o with Some v => v | None => 0 end.
Definition vals (l : list (option Z)) : list Z := map oval l.

Lemma map_nth_seq {A B} (f : A -> B) (l : list A) (d : A) :
  map f l = map (fun i => f (nth i l d)) (seq 0 (length l)).
Proof.
