  (* [comment removed for export] *)
  Definition pre (k : nat) : list Z := firstn k L.
  Definition SN (k : nat) : list Z := map wt16 (pre k).
  Definition LW (k : nat) : list Z := lows (pre k) 0.
  Definition HT (k : nat) : Z := u32 (N - 1 - Zlength (LW k)).
  Definition SY (k : nat) : list (option Z) := lp_syms N (LW k).
  Definition FM (k : nat) : Z := if existsb (fun c => largeLimit <=? c) (pre k) then 0 else 1.

