  (* [comment removed for export] *)
  Definition seg (sp : list (option Z)) (lo hi b : Z) : Prop :=
    forall i, lo <= i < hi -> nth (Z.to_nat i) sp None = Some b.
  Definition below_eq (sp sp0 : list (option Z)) (lo : Z) : Prop :=
    forall i, 0 <= i < lo -> nth (Z.to_nat i) sp None = nth (Z.to_nat i) sp0 None.

  Lemma spread_inner_spec : forall fuel sp sp0 pos i n b,
    0 <= pos -> 8 <= i -> i mod 8 = 0 -> (n <= i \/ pos + n + 7 <= Zlength sp) -> Z.max 0 (n - i) <= 8 * (Z.of_nat fuel - 1) ->
    seg sp pos (pos + i) b -> below_eq sp sp0 pos ->
    exists sp', spread_inner fuel sp pos i n b = Ok sp' /\ length sp' = length sp /\
