    (* [comment removed for export] *)
    Definition SPI (k : nat) (sp : list (option Z)) : Prop :=
      length sp = Z.to_nat (N + 8) /\
      forall i, 0 <= i < Zlength (FLk k) -> nth (Z.to_nat i) sp None = Some (nth (Z.to_nat i) (FLk k) 0).

    Lemma spread_spec : forall f k sp, (k + f = Mn)%nat -> SPI k sp ->
      exists sp', spread_loop nc f (Z.of_nat k) sp (Zlength (FLk k)) = Ok sp' /\ SPI Mn sp'.
