  (* [comment removed for export] *)
  Lemma Permutation_filter_length {A} (f : A -> bool) (l l' : list A) :
    Permutation l l' -> length (filter f l) = length (filter f l').
  Proof.
    induction 1; cbn; try reflexivity.
    - destruct (f x); cbn; lia.
    - destruct (f x), (f y); cbn; lia.
    - lia.
  Qed.

  Lemma filter_comp_length {A B} (f : B -> bool) (h : A -> B) (l : list A) :
    length (filter (fun a => f (h a)) l) = length (filter f (map h l)).
  Proof. induction l; cbn; [reflexivity|]. destruct (f (h a)); cbn; lia. Qed.

  Lemma filter_le_seq_length (h : Z) : forall n, -1 <= h -> 
    Z.of_nat (length (filter (fun v => Z.of_nat v <=? h) (seq 0 n))) = Z.min (Z.of_nat n) (h + 1).
