    Lemma sym_spec : forall fuel i g (S1 : list (option Z)) k,
      (k < Mn)%nat -> length S1 = Z.to_nat N -> GI g ->
      0 <= i -> (i <= nth k L 0 \/ i = 0) ->
      Z.of_nat (cnt g) = Zlength (FLk k) + i -> Z.max 0 (nth k L 0) - i < Z.of_nat fuel ->
      exists g', sym_loop tableLog fuel i (nth k L 0) (Z.of_nat k) (apply_writes (wsG g) S1) (PP g) (HT Mn)
                 = Ok (apply_writes (wsG g') S1, PP g')
             /\ GI g' /\ Z.of_nat (cnt g') = Zlength (FLk k) + Z.max 0 (nth k L 0).
Proof.
