    Lemma gen_spec : forall f k g (S1 : list (option Z)),
      (k + f = Mn)%nat -> length S1 = Z.to_nat N -> GI g -> Z.of_nat (cnt g) = Zlength (FLk k) ->
      exists g', gen_loop nc tableLog f (Z.of_nat k) (apply_writes (wsG g) S1) (PP g) (HT Mn)
                 = Ok (apply_writes (wsG g') S1, PP g')
