  Lemma count_lows v : 0 <= v -> Z.of_nat (count_occ Z.eq_dec (LW Mn) v) = (if nth (Z.to_nat v) L 0 =? -1 then 1 else 0) * (if v <? Zlength L then 1 else 0).
