  Definition occ (u : nat) (v : Z) : Z := Z.of_nat (count_occ Z.eq_dec (firstn u CV) v).

  Lemma occ_S u v : (u < Z.to_nat N)%nat -> occ (S u) v = occ u v + (if nth u CV 0 =? v then 1 else 0).
Proof.
