  Definition cell_ok (fm : Z) (c : dcell) : Prop :=
    0 <= dc_symbol c <= maxSV /\ 0 <= dc_nbBits c <= tableLog /\ 0 <= dc_newState c /\
    dc_newState c + 2^(dc_nbBits c) <= N /\ (fm = 1 -> 1 <= dc_nbBits c).

  Lemma FM_fast v : FM Mn = 1 -> (v < Mn)%nat -> nth v L 0 < 2^(tableLog - 1).
Proof.
