  Definition OUTOK (l : list Z) : Prop := Forall (fun b => 0 <= b <= maxSV) l /\ Zlength l <= maxDstSize.

  Lemma OUTOK_app l1 l2 : OUTOK l1 -> Forall (fun b => 0 <= b <= maxSV) l2 -> Zlength l1 + Zlength l2 <= maxDstSize -> OUTOK (l1 ++ l2).
