  Definition DI (x : dec) : Prop :=
    0 <= de_s1 x < N /\ 0 <= de_s2 x < N /\ BI (de_bd x) /\ OUTOK (de_out x).

  Lemma main_ok : forall f x, DI x -> Z.max 0 (maxDstSize - 3 - Zlength (de_out x)) <= 4 * (Z.of_nat f - 1) ->
    exists x', main_loop src dt maxDstSize fast f x = Ok x' /\ DI x'.
Proof.
