  Lemma tail_ok : forall f x, DI x -> Z.max 0 (maxDstSize - 2 - Zlength (de_out x)) <= 2 * (Z.of_nat f - 1) ->
    (exists l, tail_loop src dt maxDstSize fast f x = Ok l /\ OUTOK l) \/ (exists e, tail_loop src dt maxDstSize fast f x = Err e).
