Definition read_ncount_safe_stmt : Prop :=
  forall nc0 maxSVin buf, all_bytes buf -> 0 <= maxSVin <= FSE_MAX_SYMBOL_VALUE -> maxSVin + 1 <= Zlength nc0 ->
    (exists nc maxSV tableLog n, read_ncount nc0 maxSVin buf = Ok (nc, maxSV, tableLog, n)
       /\ 0 <= tableLog /\ (tableLog <= 14 -> ncount_ok nc maxSV tableLog)   (* [comment removed for export] *)
       /\ maxSV <= maxSVin /\ 1 <= n <= Zlength buf)
    \/ (exists e, read_ncount nc0 maxSVin buf = Err e).

Lemma all_bytes_skipn l k : all_bytes l -> all_bytes (skipn k l).
