Theorem fse_decompress_wksp_safe nc0 dstCapacity src maxLog wkspSize :
  read_ncount_safe_stmt -> all_bytes src -> 0 <= dstCapacity -> 0 <= maxLog <= FSE_MAX_TABLELOG -> 256 <= Zlength nc0 ->
  (exists l, fse_decompress_wksp nc0 dstCapacity src maxLog wkspSize = Ok l /\ Forall (fun b => 0 <= b <= 255) l /\ Zlength l <= dstCapacity)
  \/ (exists e, fse_decompress_wksp nc0 dstCapacity src maxLog wkspSize = Err e).
